-- These procedures already exist in the database. Call them.
-- Do not recreate them, and do not change them.

CREATE OR REPLACE PROCEDURE sp_part1(para_Votes integer, para_Player_name text, para_Rank integer, para_Gender text) LANGUAGE plpgsql AS
$$
DECLARE
    calc_result integer := 0;
    status_msg text;
BEGIN
    calc_result := para_Votes + 10;
    UPDATE "player" SET "Votes" = calc_result WHERE "Player_name" = para_Player_name;
    calc_result := calc_result * 2;
    DELETE FROM "coach" WHERE "Rank" = para_Rank;
    calc_result := calc_result - 5;
    UPDATE "coach" SET "Gender" = para_Gender || '_update' WHERE "Rank" = para_Rank;
    calc_result := calc_result + para_Votes;
    UPDATE "player" SET "Player_name" = para_Player_name || '_step1' WHERE "Votes" = para_Votes;
    calc_result := calc_result / 3;
    DELETE FROM "player" WHERE "Votes" < calc_result;
    status_msg := 'processing';
    UPDATE "coach" SET "Rank" = para_Rank + calc_result WHERE "Gender" = para_Gender;
    calc_result := calc_result + 15;
    UPDATE "player" SET "Votes" = calc_result WHERE "Player_name" = para_Player_name;
    calc_result := calc_result - para_Votes;
    DELETE FROM "coach" WHERE "Gender" = para_Gender || '_old';
    calc_result := calc_result * para_Votes;
    UPDATE "player" SET "Player_name" = status_msg WHERE "Votes" = para_Votes;
    calc_result := calc_result + 7;
    UPDATE "coach" SET "Rank" = calc_result WHERE "Gender" = para_Gender;
    DELETE FROM "player" WHERE "Player_name" = para_Player_name || '_step1';
    calc_result := calc_result - 12;
    UPDATE "coach" SET "Gender" = para_Gender || status_msg WHERE "Rank" = para_Rank;
END;
$$;

CREATE OR REPLACE PROCEDURE sp_part2(para_Player_id integer, para_New_votes integer) LANGUAGE plpgsql AS
$$
BEGIN
    UPDATE "player" SET "Votes" = "Votes" + para_New_votes WHERE "Player_ID" = para_Player_id;
END;
$$;

